-- Frozen schema 3, captured from the pre-refactor database initializer (2026-10-29).
-- Synthetic tests only; no production rows, identities, credentials or file paths.
PRAGMA foreign_keys=ON;
CREATE TABLE schema_version (version INTEGER PRIMARY KEY);
CREATE TABLE sessions (token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires INTEGER NOT NULL, auth_method TEXT NOT NULL DEFAULT 'password');
CREATE TABLE customers (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, normalized TEXT NOT NULL UNIQUE, short_name TEXT NOT NULL DEFAULT '', industry TEXT NOT NULL DEFAULT '', region TEXT NOT NULL DEFAULT '', level TEXT NOT NULL DEFAULT 'B' CHECK(level IN('A','B','C')), owner_id INTEGER NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT '潜在' CHECK(status IN('潜在','成交','流失','冻结')), credit_code TEXT NOT NULL DEFAULT '', scale TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, parent_company TEXT NOT NULL DEFAULT '', group_name TEXT NOT NULL DEFAULT '', tags TEXT NOT NULL DEFAULT '', compliance_flag TEXT NOT NULL DEFAULT '', ppl_id TEXT);
CREATE TABLE opportunities (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, customer_id INTEGER NOT NULL REFERENCES customers(id), owner_id INTEGER NOT NULL REFERENCES users(id), stage TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>=0), product_type TEXT NOT NULL CHECK(product_type IN('标品','实施','混合')), source TEXT NOT NULL DEFAULT '自建' CHECK(source IN('自建','分发')), nature TEXT NOT NULL DEFAULT '新签' CHECK(nature IN('新签','续签')), next_action TEXT NOT NULL DEFAULT '', follow_date TEXT, expected_date TEXT, stage_at TEXT NOT NULL, lost_reason TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, ppl_ref TEXT, ppl_stage TEXT, mirror INTEGER NOT NULL DEFAULT 0, deal_type TEXT NOT NULL DEFAULT 'new', products TEXT NOT NULL DEFAULT '', man_days REAL NOT NULL DEFAULT 0, est_margin INTEGER NOT NULL DEFAULT 0, initial_amount INTEGER, collaborator_pm INTEGER REFERENCES users(id), synced_at TEXT);
CREATE TABLE activities (id INTEGER PRIMARY KEY AUTOINCREMENT, opportunity_id INTEGER NOT NULL REFERENCES opportunities(id), user_id INTEGER NOT NULL REFERENCES users(id), source TEXT NOT NULL, activity_type TEXT NOT NULL, summary TEXT NOT NULL, action TEXT NOT NULL DEFAULT '', activity_date TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE quotes (id INTEGER PRIMARY KEY AUTOINCREMENT, opportunity_id INTEGER NOT NULL REFERENCES opportunities(id), user_id INTEGER NOT NULL REFERENCES users(id), amount INTEGER NOT NULL CHECK(amount>0), valid_until TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE contract_items (id INTEGER PRIMARY KEY AUTOINCREMENT, contract_id INTEGER NOT NULL REFERENCES contracts(id), name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN('标品','实施')), amount INTEGER NOT NULL CHECK(amount>0), rate REAL NOT NULL CHECK(rate>=0 AND rate<=1), margin INTEGER NOT NULL CHECK(margin>=0), payment_date TEXT, valid_until TEXT, man_days REAL NOT NULL DEFAULT 0);
CREATE TABLE payments (id INTEGER PRIMARY KEY AUTOINCREMENT, contract_id INTEGER NOT NULL REFERENCES contracts(id), amount INTEGER NOT NULL CHECK(amount>0), status TEXT NOT NULL CHECK(status IN('待到账','已到账','逾期')), pay_date TEXT, promise_date TEXT, note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, checkpoint_date TEXT);
CREATE TABLE targets (user_id INTEGER NOT NULL REFERENCES users(id), quarter TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>=0), PRIMARY KEY(user_id,quarter));
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE audit (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER REFERENCES users(id), action TEXT NOT NULL, entity TEXT NOT NULL, entity_id INTEGER, detail TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE mutations (key TEXT PRIMARY KEY, hash TEXT NOT NULL, response TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE "users" (id INTEGER PRIMARY KEY, name TEXT NOT NULL, username TEXT UNIQUE NOT NULL, role TEXT NOT NULL CHECK(role IN('admin','sales','pm')), password TEXT, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), created_at TEXT NOT NULL, ding_user_id TEXT, performance_enabled INTEGER NOT NULL DEFAULT 1, developer_admin INTEGER NOT NULL DEFAULT 0);
CREATE TABLE "contacts" (id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id INTEGER NOT NULL REFERENCES customers(id), name TEXT NOT NULL, title TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', role TEXT NOT NULL DEFAULT '使用人' CHECK(role IN('决策人','影响者','使用人','把关人','我方PM')), attitude TEXT NOT NULL DEFAULT '中立' CHECK(attitude IN('支持','中立','反对')), note TEXT NOT NULL DEFAULT '', wechat TEXT NOT NULL DEFAULT '', dingtalk TEXT NOT NULL DEFAULT '', last_contact TEXT);
CREATE TABLE "contracts" (id INTEGER PRIMARY KEY AUTOINCREMENT, opportunity_id INTEGER REFERENCES opportunities(id), customer_id INTEGER NOT NULL REFERENCES customers(id), owner_id INTEGER NOT NULL REFERENCES users(id), name TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>0), sign_date TEXT NOT NULL, valid_until TEXT, scope TEXT NOT NULL DEFAULT '', accept_status TEXT NOT NULL DEFAULT '待交付' CHECK(accept_status IN('待交付','交付中','待验收','已验收')), created_at TEXT NOT NULL, contract_no TEXT, recurring_amount INTEGER NOT NULL DEFAULT 0, quote_file TEXT NOT NULL DEFAULT '', auto_renew INTEGER NOT NULL DEFAULT 0, collaborator_pm INTEGER REFERENCES users(id));
CREATE TABLE customer_collaborators (customer_id INTEGER NOT NULL REFERENCES customers(id), user_id INTEGER NOT NULL REFERENCES users(id), PRIMARY KEY(customer_id,user_id));
CREATE TABLE activity_events (id INTEGER PRIMARY KEY AUTOINCREMENT, activity_id INTEGER NOT NULL REFERENCES activities(id), opportunity_id INTEGER NOT NULL REFERENCES opportunities(id), user_id INTEGER NOT NULL REFERENCES users(id), credited_user_id INTEGER NOT NULL REFERENCES users(id), source TEXT NOT NULL, activity_type TEXT NOT NULL, activity_date TEXT NOT NULL, summary TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE stage_history (id INTEGER PRIMARY KEY AUTOINCREMENT, opportunity_id INTEGER NOT NULL REFERENCES opportunities(id), from_stage TEXT, to_stage TEXT NOT NULL, at TEXT NOT NULL);
CREATE TABLE commission_batches (id INTEGER PRIMARY KEY AUTOINCREMENT, sales_id INTEGER NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN('personal','management')), period TEXT NOT NULL, base INTEGER NOT NULL, rate REAL NOT NULL, amount INTEGER NOT NULL CHECK(amount>0), status TEXT NOT NULL CHECK(status IN('confirmed','paid')), snapshot TEXT NOT NULL, created_at TEXT NOT NULL, confirmed_by INTEGER NOT NULL REFERENCES users(id), paid_at TEXT, paid_note TEXT NOT NULL DEFAULT '');
CREATE TABLE commission_lines (id INTEGER PRIMARY KEY AUTOINCREMENT, batch_id INTEGER NOT NULL REFERENCES commission_batches(id), contract_id INTEGER NOT NULL REFERENCES contracts(id), item_id INTEGER NOT NULL REFERENCES contract_items(id), base INTEGER NOT NULL, rebate_rate REAL NOT NULL, rate REAL NOT NULL, amount INTEGER NOT NULL);
CREATE TABLE performance_reviews (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id), month TEXT NOT NULL, adjustment REAL, reason TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','confirmed')), snapshot TEXT, reviewed_by INTEGER REFERENCES users(id), updated_at TEXT NOT NULL, UNIQUE(user_id,month));
CREATE TABLE capture_drafts (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id), source TEXT NOT NULL, external_id TEXT, payload TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'draft', created_at TEXT NOT NULL, confirmed_at TEXT, UNIQUE(source,external_id));
CREATE TABLE change_requests (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id), entity TEXT NOT NULL, entity_id INTEGER, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL, reviewed_at TEXT, reason TEXT NOT NULL DEFAULT '');
CREATE TABLE sync_runs (id INTEGER PRIMARY KEY AUTOINCREMENT, source TEXT NOT NULL, count INTEGER NOT NULL, created_at TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '{}');
CREATE TABLE daily_reports (day TEXT PRIMARY KEY, snapshot TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE ding_identities (user_id INTEGER PRIMARY KEY REFERENCES users(id), union_id TEXT NOT NULL UNIQUE);
CREATE UNIQUE INDEX customers_credit ON customers(credit_code) WHERE credit_code!='';
CREATE INDEX opportunities_owner ON opportunities(owner_id, stage);
CREATE INDEX activities_opp ON activities(opportunity_id, activity_date);
CREATE INDEX payments_contract ON payments(contract_id,status);
CREATE UNIQUE INDEX users_ding ON users(ding_user_id) WHERE ding_user_id IS NOT NULL AND ding_user_id!='';
CREATE UNIQUE INDEX contracts_number ON contracts(contract_no) WHERE contract_no IS NOT NULL;
CREATE INDEX contracts_owner ON contracts(owner_id,sign_date);
CREATE UNIQUE INDEX opportunity_ppl ON opportunities(ppl_ref) WHERE ppl_ref IS NOT NULL;
CREATE UNIQUE INDEX customer_ppl ON customers(ppl_id) WHERE ppl_id IS NOT NULL;
CREATE INDEX commission_period ON commission_batches(period,sales_id,kind);
