INSERT INTO settings(key,value) VALUES('rules','{"thresholds":{"线索":5,"初步接触":4,"需求确认":3,"方案沟通":5,"报价":5,"POC 试用":10,"商务谈判":3},"sop":{"线索":"明确客户需求、决策链与预算窗口","初步接触":"建立关键人联系，约定深入沟通时间","需求确认":"梳理需求清单，请客户确认范围","方案沟通":"形成针对性方案，确认实施与验收条件","报价":"拆分标品与实施，说明有效期并约定回访","POC 试用":"约定成功标准，记录试用反馈与验收结果","商务谈判":"确认采购流程、付款节点，先签合同再垫付实施费","成交":"明确交付范围、验收与回款节点","流失":"记录真实原因，保留后续接触线索"},"commission_visible":true,"result_visible":true,"commission":{"period":"quarter","threshold":20000000,"low_rate":0.03,"high_rate":0.05,"manager_id":null,"unlock_by_payment":false,"standard_self_new":0.45,"standard_distributed_new":0.35,"standard_renewal":0.25,"implementation":0.5},"performance":{"process_weight":70,"result_weight":30,"cap":50,"meeting":0.5,"visit":1,"quote":0.5,"grades":[{"min":90,"grade":"A","factor":1.1},{"min":75,"grade":"B","factor":0.9},{"min":60,"grade":"C","factor":0.6},{"min":0,"grade":"D","factor":0.4}]},"mirror_mode":true,"attention_ratio":0.8,"inactivity_days":30,"contact_days":30}');
